//! Keyboard map built from Trilium's own default shortcut table
//! (`assets/keyboard-actions.json`, generated by tools/extract_shortcuts.py), so key names and
//! bindings match the browser app. `CommandOrControl` means Ctrl on Linux.
//! User overrides: `~/.config/trilium-tui/keys.json` = `{"jumpToNote": ["Ctrl+K"], "quickSearch": []}`.
use ratatui::crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use serde::Deserialize;
use std::collections::HashMap;

