#[derive(Clone, Debug, PartialEq, Eq)]
pub struct KeySpec {
    code: KeyCode,
    ctrl: bool,
    alt: bool,
    shift: bool,
}

impl KeySpec {
    pub fn parse(spec: &str) -> Option<Self> {
        if spec.starts_with("global:") { return None; } // OS-wide hotkeys are out of scope for a TUI
        let (mut ctrl, mut alt, mut shift) = (false, false, false);
        let mut key = None;
        // "Ctrl++" style: a trailing "+" is the key itself
        let (head, tail) = match spec.strip_suffix("++") { Some(h) => (format!("{h}+"), Some("+")), None => (spec.to_string(), None) };
        let mut parts: Vec<&str> = head.split('+').filter(|p| !p.is_empty()).collect();
        if let Some(t) = tail { parts.push(t); }
        for p in parts {
            match p {
                "CommandOrControl" | "Ctrl" | "Control" | "CmdOrCtrl" => ctrl = true,
                "Alt" | "Option" => alt = true,
                "Shift" => shift = true,
                "Plus" => key = Some(KeyCode::Char('+')),
                "Left" => key = Some(KeyCode::Left),
                "Right" => key = Some(KeyCode::Right),
                "Up" => key = Some(KeyCode::Up),
                "Down" => key = Some(KeyCode::Down),
                "Tab" => key = Some(KeyCode::Tab),
                "Enter" | "Return" => key = Some(KeyCode::Enter),
                "Delete" => key = Some(KeyCode::Delete),
                "Backspace" => key = Some(KeyCode::Backspace),
                "Escape" | "Esc" => key = Some(KeyCode::Esc),
                "PageUp" => key = Some(KeyCode::PageUp),
                "PageDown" => key = Some(KeyCode::PageDown),
                "Home" => key = Some(KeyCode::Home),
                "End" => key = Some(KeyCode::End),
                "Space" => key = Some(KeyCode::Char(' ')),
                f if f.len() >= 2 && f.starts_with('F') && f[1..].chars().all(|c| c.is_ascii_digit()) => {
                    key = Some(KeyCode::F(f[1..].parse().ok()?));
                }
                c if c.chars().count() == 1 => key = Some(KeyCode::Char(c.chars().next()?.to_ascii_lowercase())),
                _ => return None,
            }
        }
        Some(Self { code: key?, ctrl, alt, shift })
    }

    pub fn matches(&self, ev: &KeyEvent) -> bool {
        let m = ev.modifiers;
        if m.contains(KeyModifiers::CONTROL) != self.ctrl || m.contains(KeyModifiers::ALT) != self.alt { return false; }
        let ev_shift = m.contains(KeyModifiers::SHIFT);
        match (self.code, ev.code) {
            (KeyCode::Tab, KeyCode::BackTab) => self.shift,
            (KeyCode::Char(a), KeyCode::Char(b)) => {
                let upper = b.is_uppercase();
                a == b.to_ascii_lowercase() && (self.shift == (ev_shift || upper) || (!a.is_alphabetic() && !self.shift))
            }
            (a, b) => a == b && self.shift == ev_shift,
        }
    }

    pub fn label(&self) -> String {
        let mut s = String::new();
        if self.ctrl { s += "Ctrl+"; }
        if self.alt { s += "Alt+"; }
        if self.shift { s += "Shift+"; }
        s += &match self.code {
            KeyCode::Char(c) => c.to_ascii_uppercase().to_string(),
            other => format!("{other}"),
        };
        s
    }
}

#[derive(Deserialize)]
struct SpecRow {
    action: String,
    keys: Vec<String>,
}

pub struct Keymap {
    bindings: Vec<(KeySpec, Action)>,
    /// total / implemented counts for the help screen
    pub total_actions: usize,
}

impl Keymap {
    pub fn load() -> Self {
        let rows: Vec<SpecRow> = serde_json::from_str(include_str!("../assets/keyboard-actions.json")).expect("bundled keymap");
        let mut keys: HashMap<String, Vec<String>> = rows.iter().map(|r| (r.action.clone(), r.keys.clone())).collect();
        let total_actions = rows.iter().filter(|r| !r.keys.is_empty()).count();
        let overrides = dirs::config_dir()
            .map(|d| d.join("trilium-tui").join("keys.json"))
            .and_then(|p| std::fs::read_to_string(p).ok())
            .and_then(|s| serde_json::from_str::<HashMap<String, Vec<String>>>(&s).ok());
        let overridden: std::collections::HashSet<String> = overrides.as_ref().map(|o| o.keys().cloned().collect()).unwrap_or_default();
        if let Some(o) = overrides { keys.extend(o); }
        // a fixed order, the user's own bindings first: when two actions claim one key, the user's wins every time (not whichever
        // the hash map happened to yield)
        let mut names: Vec<&String> = keys.keys().collect();
        names.sort_by_key(|n| (!overridden.contains(*n), (*n).clone()));
        let mut bindings = Vec::new();
        for name in names {
            let specs = &keys[name];
            if let Some(action) = Action::from_name(name) {
                bindings.extend(specs.iter().filter_map(|s| KeySpec::parse(s)).map(|k| (k, action)));
            }
        }
        Self { bindings, total_actions }
    }

    pub fn action_for(&self, ev: &KeyEvent) -> Option<Action> {
        self.bindings.iter().find(|(k, _)| k.matches(ev)).map(|(_, a)| *a)
    }

    pub fn labels_for(&self, action: Action) -> Vec<String> {
        let mut v: Vec<String> = self.bindings.iter().filter(|(_, a)| *a == action).map(|(k, _)| k.label()).collect();
        v.sort();
        v
    }

    pub fn implemented(&self) -> usize {
        let mut a: Vec<Action> = self.bindings.iter().map(|(_, a)| *a).collect();
        a.sort_by_key(|x| format!("{x:?}"));
        a.dedup();
        a.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn key(c: KeyCode, m: KeyModifiers) -> KeyEvent { KeyEvent::new(c, m) }

    #[test]
    fn parses_and_matches_trilium_specs() {
        let j = KeySpec::parse("CommandOrControl+J").unwrap();
        assert!(j.matches(&key(KeyCode::Char('j'), KeyModifiers::CONTROL)));
        assert!(!j.matches(&key(KeyCode::Char('j'), KeyModifiers::NONE)));
        let sj = KeySpec::parse("CommandOrControl+Shift+J").unwrap();
        assert!(sj.matches(&key(KeyCode::Char('J'), KeyModifiers::CONTROL | KeyModifiers::SHIFT)));
        assert!(!sj.matches(&key(KeyCode::Char('j'), KeyModifiers::CONTROL)), "plain Ctrl+J must not trigger Ctrl+Shift+J");
        assert!(KeySpec::parse("Alt+Left").unwrap().matches(&key(KeyCode::Left, KeyModifiers::ALT)));
        assert!(KeySpec::parse("Alt+-").unwrap().matches(&key(KeyCode::Char('-'), KeyModifiers::ALT)));
        assert!(KeySpec::parse("CommandOrControl+.").unwrap().matches(&key(KeyCode::Char('.'), KeyModifiers::CONTROL)));
        assert!(KeySpec::parse("F5").unwrap().matches(&key(KeyCode::F(5), KeyModifiers::NONE)));
        assert!(KeySpec::parse("global:CommandOrControl+Alt+P").is_none());
        assert!(KeySpec::parse("CommandOrControl+Plus").is_some());
    }

    #[test]
    fn bundled_table_loads_with_expected_bindings() {
        let km = Keymap::load();
        assert_eq!(km.action_for(&key(KeyCode::Char('j'), KeyModifiers::CONTROL)), Some(Action::JumpToNote));
        assert_eq!(km.action_for(&key(KeyCode::Left, KeyModifiers::ALT)), Some(Action::Back));
        assert_eq!(km.action_for(&key(KeyCode::F(1), KeyModifiers::NONE)), Some(Action::Help));
        assert!(km.total_actions > 50);
    }
}
